"""Prepare generic QX scripts before publishing any synchronized configuration.

Upstream JavaScript is preserved verbatim inside a shared API facade. Validation
uses Node's parser only; synchronization never executes third-party scripts.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path, PurePosixPath
import re
import subprocess
from urllib.parse import urlsplit

from _common import write_if_changed
from module_convert import module_targets, parse_module, _options
from qx_convert import convert_qx_module, is_qx_module
from qx_compat import can_use_upstream, requires_binary_body


OWNERS_FILE = ".github/scripts/qx-scripts-owned.json"
GENERATED_HEADER = "// Generated by .github/scripts/qx_scripts.py; do not edit."
SCRIPT_DIRECTORY = "Surge/Module/Scripts"
RAW_SCRIPT_BASE = "https://raw.githubusercontent.com/HotKids/Rules/refs/heads/master/" + SCRIPT_DIRECTORY + "/"
_MODES = {"request", "request-body", "response", "response-body", "echo", "cron"}
_OWNED_NAME = re.compile(r"Surge/Module/Scripts/[a-z0-9][a-z0-9._-]*\.js")


def _digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _safe_path(root, relative):
    path = root / relative
    if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Unsafe QX generated-script path")
    return path


def _read_owners(root):
    path = _safe_path(root, OWNERS_FILE)
    if not path.exists():
        return {}
    state = json.loads(path.read_text(encoding="utf-8"))
    if (not isinstance(state, dict) or state.get("version") != 1
            or not isinstance(state.get("files"), dict)):
        raise ValueError("Invalid QX script ownership record")
    files = state["files"]
    if any(not isinstance(name, str) or not _OWNED_NAME.fullmatch(name)
           or not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)
           for name, digest in files.items()):
        raise ValueError("Invalid QX script ownership path or fingerprint")
    return dict(files)


def _owned_content(path, digest):
    if not path.is_file():
        return False
    content = path.read_bytes()
    return (hashlib.sha256(content).hexdigest() == digest
            and content.startswith((GENERATED_HEADER + "\n").encode("utf-8")))


def _bundle_script(routes, bodies, runtime):
    urls = list(dict.fromkeys(route["url"] for route in routes))
    sources = []
    for url in urls:
        # Keep the original function body and directive prologue verbatim. The
        # facade lives one scope outside it so local Env/module shims still work.
        sources.append("function ($request, $response, $prefs, $notify, $task, $done) {\n"
                       "return (function () {\n// BEGIN UPSTREAM SOURCE\n" + bodies[url]
                       + "\n// END UPSTREAM SOURCE\n}).call(this);\n}")
    table = [{"name": route["name"], "type": route["type"], "pattern": route.get("pattern"),
              "mode": route["mode"], "source": urls.index(route["url"]),
              "namespace": "qx-" + _digest(route["url"])} for route in routes]
    return (GENERATED_HEADER + "\n(function (native) {\n" + runtime.rstrip() + "\n"
            + "const sources = [\n" + ",\n".join(sources) + "\n];\n"
            + "const routes = " + json.dumps(table, ensure_ascii=False) + ";\n"
            + """const label = native.script && native.script.name;
let matches = typeof label === 'string' ? routes.filter(route => route.name === label) : [];
if (matches.length === 0) {
  const declared = native.script && native.script.type;
  const stage = ['http-request', 'http-response', 'cron'].includes(declared) ? declared
    : native.response ? 'http-response' : native.request ? 'http-request' : 'cron';
  const url = native.request && native.request.url;
  matches = routes.filter(route => {
    if (stage === 'cron' || route.type !== stage || typeof url !== 'string') return false;
    try { return new RegExp(route.pattern).test(url); } catch (_) { return false; }
  });
  // Overlapping patterns for the same source and mode execute identical code.
  matches = matches.filter((route, index, all) => all.findIndex(other =>
    other.source === route.source && other.mode === route.mode) === index);
}
if (matches.length !== 1) return native.done({});
const route = matches[0];
const bridge = createQxRuntime(native, route.mode, route.namespace);
return sources[route.source].call(this, bridge.request, bridge.response, bridge.prefs, bridge.notify, bridge.task, bridge.done);
})({
"""
            + "request: typeof $request === 'undefined' ? undefined : $request,\n"
            + "response: typeof $response === 'undefined' ? undefined : $response,\n"
            + "script: typeof $script === 'undefined' ? undefined : $script,\n"
            + "persistentStore: typeof $persistentStore === 'undefined' ? undefined : $persistentStore,\n"
            + "notification: typeof $notification === 'undefined' ? undefined : $notification,\n"
            + "httpClient: typeof $httpClient === 'undefined' ? undefined : $httpClient,\n"
            + "done: typeof $done === 'undefined' ? undefined : $done,\n"
            + "platform: typeof $environment !== 'undefined' && ($environment['stash-version'] || $environment['stash-build']) ? 'stash' : 'surge'\n"
            + "});\n")


def _validate_script(content, identifier):
    try:
        result = subprocess.run(["node", "--check"], input=content, text=True,
                                capture_output=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        raise RuntimeError("QX script syntax validation requires a working Node.js parser") from None
    if result.returncode:
        # Parser stderr includes source lines; never repeat credentials, response
        # examples or query strings from an upstream script in public CI logs.
        raise ValueError(f"QX script syntax validation failed: {identifier}")


class PreparedQxModules:
    def __init__(self, root, entries, sources, converted, scripts, owners):
        self.root = root.resolve()
        self.entries = json.dumps(entries, sort_keys=True)
        self.sources = {url: _digest(body) for url, body in sources.items()}
        self.converted_by_target = converted
        self.converted = {}
        for (_target, url), text in converted.items():
            self.converted.setdefault(url, text)
        self.scripts = scripts
        self.owners = owners

    def validate_inputs(self, root, entries, prefetched):
        sources = {entry["url"]: prefetched.get(entry["url"]) or "" for entry in entries}
        if (root.resolve() != self.root
                or json.dumps(entries, sort_keys=True) != self.entries
                or {url: _digest(body) for url, body in sources.items()} != self.sources):
            raise ValueError("Prepared QX script batch does not match module sources")

    def source_text(self, url, target, fallback):
        return self.converted_by_target.get((target, url), fallback)

    def validate_destinations(self):
        # Reject conflicting edits for the complete batch before writing even
        # the first script. Unknown files may only be adopted when byte-equal.
        for relative in self.owners:
            _safe_path(self.root, relative)
        for relative, content in self.scripts.items():
            path = _safe_path(self.root, relative)
            if path.exists() and path.read_bytes() != content.encode("utf-8"):
                if relative not in self.owners or not _owned_content(path, self.owners[relative]):
                    raise ValueError(f"Generated QX script has local edits; refusing to overwrite: {relative}")

    def write_scripts(self):
        self.validate_destinations()
        for relative, content in self.scripts.items():
            write_if_changed(_safe_path(self.root, relative), content)

    def finish(self):
        """Clean only fingerprinted, unedited wrappers after modules are written."""
        for relative, digest in self.owners.items():
            if relative in self.scripts:
                continue
            path = _safe_path(self.root, relative)
            if path.exists() and _owned_content(path, digest):
                path.unlink()
            elif path.exists():
                print(f"  [WARN] {relative} 已手动修改，保留并解除 QX 自动清理归属")
        files = {name: _digest(content) for name, content in sorted(self.scripts.items())}
        if files or self.owners or (self.root / OWNERS_FILE).exists():
            state = {"version": 1, "files": files}
            write_if_changed(_safe_path(self.root, OWNERS_FILE),
                             json.dumps(state, ensure_ascii=False, indent=2) + "\n")


def prepare_qx_modules(entries, prefetched, root, download_scripts):
    """Keep compatible JS upstream and bundle only scripts needing the QX facade.

    The returned plan performs no filesystem changes until explicitly committed.
    Native Surge modules pass through without fetching or wrapping their scripts.
    """
    root = Path(root)
    sources = {entry["url"]: prefetched.get(entry["url"]) or "" for entry in entries}
    converted, references, groups = {}, {}, {}
    qx = {url for url, text in sources.items()
          if urlsplit(url).path.lower().endswith(".snippet") or is_qx_module(text)}
    if qx:
        for entry in entries:
            for target in module_targets(entry["name"]):
                groups.setdefault(target, []).append(entry)

    def script_url(url, mode):
        if mode not in _MODES:
            raise ValueError("Unsupported QX script execution mode")
        identifier = "qx-" + _digest(url + "\0" + mode) + ".js"
        references.setdefault((url, mode), identifier)
        return RAW_SCRIPT_BASE + identifier

    # Resolve labels using the same first-source metadata policy as merge_modules.
    plans = {}
    for target, members in groups.items():
        if not any(entry["url"] in qx for entry in members):
            continue
        first = members[0]
        title = next((match[1].strip() for line in sources[first["url"]].lstrip("\ufeff").splitlines()
                      if (match := re.match(r"\s*#!\s*name\s*=(.*)", line))), "QX")
        title = first.get("overrides", {}).get("name", title)
        start, source_plans, routes = 0, {}, []
        native_labels = set()
        for entry in members:
            url = entry["url"]
            if url in source_plans:
                continue
            if url not in qx:
                _, sections = parse_module(sources[url])
                native_labels.update(line.split("=", 1)[0].strip() for line in sections.get("Script", [])
                                     if "=" in line and not line.lstrip().startswith(("#", "//")))
                continue
            text = convert_qx_module(sources[url], script_url=script_url,
                                     script_prefix=title, script_start=start)
            _, sections = parse_module(text)
            source_routes = []
            reverse = {RAW_SCRIPT_BASE + identifier: pair for pair, identifier in references.items()}
            for line in sections.get("Script", []):
                if not line.strip() or line.lstrip().startswith(("#", "//")):
                    continue
                label, value = line.split("=", 1)
                options = _options(value, ",")
                original, mode = reverse[options["script-path"]]
                source_routes.append({"name": label.strip(), "url": original, "mode": mode,
                                      "type": options["type"], "pattern": options.get("pattern")})
            source_plans[url] = (title, start)
            start += len(source_routes)
            routes.extend(source_routes)
        if native_labels.intersection(route["name"] for route in routes):
            raise ValueError("QX script labels collide with native scripts in the same module")
        plans[target] = (source_plans, routes)

    bodies, direct, binary = {}, set(), set()
    if references:
        urls = list(dict.fromkeys(url for url, _mode in references))
        bodies = download_scripts(urls)
        for url in urls:
            body = bodies.get(url)
            identifier = "source-" + _digest(url)[:12]
            if not isinstance(body, str) or not body.strip() or "\0" in body:
                raise ValueError(f"QX script download is empty or invalid: {identifier}")
            if re.match(r"\s*(?:<!doctype\s+html|<html\b)", body, re.I):
                raise ValueError(f"QX script download returned HTML: {identifier}")
            # Node stdin has CommonJS parameters such as `module`, unlike the
            # proxy script scope. A standalone function body avoids rejecting
            # valid local declarations while still parsing without execution.
            _validate_script("(function () {\n" + body + "\n});\n", identifier)
            if requires_binary_body(body):
                binary.add(url)
            modes = {mode for ref, mode in references if ref == url}
            if all(can_use_upstream(body, mode) for mode in modes):
                direct.add(url)
    scripts, identities = {}, {}
    runtime = None
    for target, (source_plans, routes) in plans.items():
        adapted = [route for route in routes if route["url"] not in direct]
        bundle_url = None
        if adapted:
            identity = PurePosixPath(target).with_suffix("").as_posix()
            basename = PurePosixPath(identity).name.lower() + ".js"
            relative = SCRIPT_DIRECTORY + "/" + basename
            if not _OWNED_NAME.fullmatch(relative):
                raise ValueError("QX bundle requires a lowercase ASCII module basename")
            if relative in identities and identities[relative] != identity:
                raise ValueError("QX module basenames collide after lowercasing")
            identities[relative] = identity
            if runtime is None:
                runtime = Path(__file__).with_name("qx-runtime.js").read_text(encoding="utf-8")
            content = _bundle_script(adapted, bodies, runtime)
            if relative in scripts and scripts[relative] != content:
                raise ValueError("QX module formats require conflicting bundles with the same basename")
            _validate_script(content, basename)
            scripts[relative] = content
            bundle_url = RAW_SCRIPT_BASE + basename
        for url, (title, start) in source_plans.items():
            converted[(target, url)] = convert_qx_module(
                sources[url], script_prefix=title, script_start=start, binary_body_urls=binary,
                script_url=lambda original, _mode: original if original in direct else bundle_url)
    owners = _read_owners(root)
    batch = PreparedQxModules(root, entries, sources, converted, scripts, owners)
    # Ownership/path conflicts are errors before any rules or modules are written.
    batch.validate_destinations()
    return batch
